def get_mock_pvgis_tmy_result() -> PVGISTMYResult:
    """Generate synthetic 8760 hourly TMY records for Rome (41.9N, 12.5E).

    Uses sinusoidal GHI curves with seasonal variation.
    Calibrated so 6 kWp * 0.86 efficiency yields ~7500-9500 kWh/year.
    """
    # Per-month: (sunrise_hour, sunset_hour, peak_ghi_wm2, avg_temp_c)
    _MONTH_PARAMS = [
        (7, 17, 300, 7),    # Jan
        (7, 18, 380, 9),    # Feb
        (6, 18, 480, 12),   # Mar
        (6, 19, 580, 15),   # Apr
        (5, 20, 700, 20),   # May
        (5, 21, 780, 24),   # Jun
        (5, 21, 800, 27),   # Jul
        (6, 20, 720, 27),   # Aug
        (6, 19, 560, 23),   # Sep
        (7, 18, 400, 17),   # Oct
        (7, 17, 310, 12),   # Nov
        (7, 17, 270, 8),    # Dec
    ]

    records: list[PVGISHourlyRecord] = []
    hour_index = 0

    for month_idx, hours_in_month in enumerate(_MONTH_HOURS):
        sunrise, sunset, peak_ghi, avg_temp = _MONTH_PARAMS[month_idx]
        days_in_month = hours_in_month // 24
        daylight_hours = sunset - sunrise

        for day in range(days_in_month):
            for hour in range(24):
                if sunrise <= hour < sunset:
                    # Sinusoidal curve between sunrise and sunset
                    frac = (hour - sunrise + 0.5) / daylight_hours
                    ghi = peak_ghi * math.sin(math.pi * frac)
                else:
                    ghi = 0.0

                # Daily temperature variation: +4C at 14:00, -4C at 05:00
                temp = avg_temp + 4.0 * math.sin(math.pi * (hour - 5) / 12)

                # Split GHI into beam and diffuse with the Rome sun position so
                # the tilted-plane model has components to work with.
                _, _, cos_z = _sun_geometry(hour_index // 24 + 1, hour - 0.5, 41.9, 12.5)  # local CET to UTC
                dhi = 0.35 * ghi
                dni = (ghi - dhi) / cos_z if cos_z > 0.1 else 0.0
                if dni == 0.0:
                    dhi = ghi

                records.append(PVGISHourlyRecord(
                    hour_index=hour_index,
                    ghi_wm2=round(ghi, 1),
                    temperature_c=round(temp, 1),
                    wind_speed_ms=3.0,
                    dni_wm2=round(dni, 1),
                    dhi_wm2=round(dhi, 1),
                ))
                hour_index += 1

    return PVGISTMYResult(records=records, location="41.9,12.5", lat=41.9, lon=12.5)


def parse_tmy_response(data: dict, lat: float, lon: float) -> PVGISTMYResult:
    """Parse a raw PVGIS /tmy JSON response."""
    hourly_data = data["outputs"]["tmy_hourly"]
    if len(hourly_data) != 8760:
        raise ValueError(
            f"PVGIS TMY returned {len(hourly_data)} records, expected 8760"
        )

    records = [
        PVGISHourlyRecord(
            hour_index=i,
            ghi_wm2=max(0.0, h["G(h)"]),
            temperature_c=h["T2m"],
            # ERA5 reanalysis can return small negative values (e.g. -0.04 m/s)
            wind_speed_ms=max(0.0, h.get("WS10m", 0.0)),
            dni_wm2=max(0.0, h["Gb(n)"]) if "Gb(n)" in h else None,
            dhi_wm2=max(0.0, h["Gd(h)"]) if "Gd(h)" in h else None,
        )
        for i, h in enumerate(hourly_data)
    ]
    offset = data.get("inputs", {}).get("location", {}).get("irradiance_time_offset", 0.0)
    return PVGISTMYResult(
        records=records,
        location=f"{lat},{lon}",
        lat=lat,
        lon=lon,
        irradiance_time_offset_h=offset or 0.0,
    )


def tmy_to_hourly_kw(
    tmy: PVGISTMYResult, kwp: float, system_efficiency: float = 0.86
) -> list[float]:
    """Convert TMY GHI data to hourly kW production.

    Formula: kw = ghi * kwp * system_efficiency / 1000
    Default efficiency 0.86 matches existing system_loss=14% convention.
    """
    return [r.ghi_wm2 * kwp * system_efficiency / 1000 for r in tmy.records]
